/**\n * Color System for IPTV Android App\n * Kotlin implementation of the design system colors\n * Use these colors throughout your Android TV app\n */\n\npackage com.example.iptvapp.ui.theme\n\nimport androidx.compose.ui.graphics.Color\n\n// ==================== PRIMARY COLORS ====================\nval PrimaryDark = Color(0xFF1C2846)           // #1C2846 - Main brand color\nval PrimaryForeground = Color(0xFFFAFBFE)    // #FAFBFE - Text on primary\n\n// ==================== SECONDARY COLORS ====================\nval Secondary = Color(0xFF2D3F52)            // #2D3F52 - Secondary elements\nval SecondaryForeground = Color(0xFFFAFBFE) // #FAFBFE - Text on secondary\n\n// ==================== BACKGROUND COLORS ====================\nval Background = Color(0xFF0E131E)           // #0E131E - Main app background\nval Foreground = Color(0xFFFAFBFE)           // #FAFBFE - Main text color\nval Card = Color(0xFF1A2332)                 // #1A2332 - Card backgrounds\nval Border = Color(0xFF1E2D3D)               // #1E2D3D - Border colors\n\n// ==================== ACCENT COLORS (FOCUS/INTERACTION) ====================\nval AccentYellow = Color(0xFFCACA00)         // #CACA00 - Focus indicator (PRIMARY)\nval AccentYellowForeground = Color(0xFF26310B) // #26310B - Text on yellow\n\nval AccentBlue = Color(0xFF3B82F6)           // #3B82F6 - Hover state\nval AccentBlueDark = Color(0xFF2563EB)      // #2563EB - Selected state\n\n// ==================== STATE COLORS ====================\nval Success = Color(0xFF10B981)              // #10B981 - Green/Success\nval Error = Color(0xFFEF4444)                // #EF4444 - Red/Error\nval Warning = Color(0xFFF59E0B)              // #F59E0B - Yellow/Warning\nval Info = Color(0xFF3B82F6)                 // #3B82F6 - Blue/Info\nval Muted = Color(0xFF64748B)                // #64748B - Slate/Muted\n\n// ==================== QUALITY BADGE COLORS ====================\n\n// 4K Badge\nval Badge4KBackground = Color(0xFF7F1D1D)    // Red-900\nval Badge4KText = Color(0xFFFCA5A5)          // Red-200\n\n// HD Badge\nval BadgeHDBackground = Color(0xFF1E3A8A)    // Blue-900\nval BadgeHDText = Color(0xFF93C5FD)          // Blue-300\n\n// EPG Badge\nval BadgeEPGBackground = Color(0xFF334155)   // Slate-700\nval BadgeEPGText = Color(0xFFE2E8F0)         // Slate-200\n\n// Premium ($) Badge\nval BadgePremiumBackground = Color(0xFF78350F) // Yellow-900\nval BadgePremiumText = Color(0xFFFEF08A)     // Yellow-200\n\n// ==================== SHADE VARIANTS ====================\n\n// Slate shades\nval Slate50 = Color(0xFFF8FAFC)\nval Slate100 = Color(0xFFF1F5F9)\nval Slate200 = Color(0xFFE2E8F0)\nval Slate300 = Color(0xFFCBD5E1)\nval Slate400 = Color(0xFF94A3B8)\nval Slate500 = Color(0xFF64748B)\nval Slate600 = Color(0xFF475569)\nval Slate700 = Color(0xFF334155)\nval Slate800 = Color(0xFF1E293B)\nval Slate900 = Color(0xFF0F172A)\nval Slate950 = Color(0xFF020617)\n\n// Red shades (for 4K badge variants)\nval Red900 = Color(0xFF7F1D1D)\nval Red800 = Color(0xFF991B1B)\nval Red200 = Color(0xFFFCA5A5)\nval Red100 = Color(0xFFFEE2E2)\n\n// Blue shades (for HD badge and accent)\nval Blue900 = Color(0xFF1E3A8A)\nval Blue800 = Color(0xFF1E40AF)\nval Blue400 = Color(0xFF60A5FA)\nval Blue300 = Color(0xFF93C5FD)\nval Blue100 = Color(0xFFDEEDFF)\n\n// Yellow shades (for premium badge and focus)\nval Yellow900 = Color(0xFF78350F)\nval Yellow800 = Color(0xFF92400E)\nval Yellow400 = Color(0xFFFAAC34)\nval Yellow200 = Color(0xFFFEF08A)\n\n// ==================== SEMANTIC COLORS ====================\nval Success500 = Color(0xFF10B981)           // Checkmark, success states\nval SuccessLight = Color(0xFFD1FAE5)         // Light background\nval SuccessDark = Color(0xFF065F46)          // Dark variant\n\nval Error500 = Color(0xFFEF4444)             // Error states, destructive\nval ErrorLight = Color(0xFFFEE2E2)           // Light background\nval ErrorDark = Color(0xFF7F1D1D)            // Dark variant\n\nval Warning500 = Color(0xFFF59E0B)           // Warning states\nval WarningLight = Color(0xFFFEF3C7)         // Light background\nval WarningDark = Color(0xFF78350F)          // Dark variant\n\nval Info500 = Color(0xFF3B82F6)              // Info/Tertiary\nval InfoLight = Color(0xFFEFF6FF)            // Light background\nval InfoDark = Color(0xFF1E3A8A)             // Dark variant\n\n// ==================== UTILITY COLORS ====================\nval Transparent = Color(0x00000000)\nval Black = Color(0xFF000000)\nval White = Color(0xFFFFFFFF)\n\n// ==================== GLASS MORPHISM ====================\nval GlassLight = Color(0x0DFFFFFF)           // 5% white overlay\nval GlassMedium = Color(0x1AFFFFFF)          // 10% white overlay\nval GlassTransparentBorder = Color(0x1AFFFFFF) // 10% for borders\n\n// ==================== OVERLAY & SHADOWS ====================\nval ShadowLight = Color(0x0D000000)          // 5% black overlay\nval ShadowMedium = Color(0x1A000000)         // 10% black overlay\nval ShadowDark = Color(0x26000000)           // 15% black overlay\n\n// ==================== HELPER FUNCTION ====================\n/**\n * Get quality badge colors based on quality type\n * @param quality The quality type (\"4K\", \"HD\", \"EPG\", \"$\")\n * @return Pair<Background, TextColor>\n */\nfun getQualityBadgeColors(quality: String): Pair<Color, Color> {\n    return when (quality) {\n        \"4K\" -> Badge4KBackground to Badge4KText\n        \"HD\" -> BadgeHDBackground to BadgeHDText\n        \"EPG\" -> BadgeEPGBackground to BadgeEPGText\n        \"$\" -> BadgePremiumBackground to BadgePremiumText\n        else -> BadgeEPGBackground to BadgeEPGText\n    }\n}\n\n/**\n * Create a color with opacity\n * @param color The base color\n * @param opacity Opacity percentage (0-100)\n * @return Color with opacity applied\n */\nfun Color.withOpacity(opacity: Int): Color {\n    val alpha = (opacity * 255 / 100).coerceIn(0, 255)\n    return this.copy(alpha = (alpha / 255f))\n}\n"
}
